from pathlib import Path
p=Path(__file__).resolve().parent;s=(p/'ui_base.html').read_text().replace('Ecossistema 01','Ecossistema 02 | Flora').replace('laboratório de processos naturais','laboratório de biodiversidade vegetal').replace('let state=Eco.create()','let state=Flora.create()').replace('state=Eco.create()','state=Flora.create()').replace('Eco.tick(state)','Flora.tick(state)').replace('Eco.edit(state,sel,id)','Flora.edit(state,sel,id)').replace('ivEco030','ivEco031').replace('<option value="land">Paisagem</option>','<option value="species">Espécies</option><option value="land">Paisagem</option><option value="phenology">Fases vegetais</option>').replace("$('layer').value='land'","$('layer').value='species'").replace('<label for="light">Luz</label>','<label for="pollinators">Polinizadores</label><select id="pollinators"><option value="normal">Presentes (modelo)</option><option value="noMoth">Sem mariposa da orquídea</option><option value="none">Ausentes</option></select><label for="light">Luz</label>').replace('<h2>Estado da bacia</h2>','<h2>Estado da bacia</h2><div id="floraStats" class="fine"></div><div id="population" class="fine"></div>').replace('<button id="water">Irrigar</button>','<button id="water">Irrigar</button><button id="harvest">Colher frutos</button><select id="seedSelect" aria-label="Espécie para semear"></select><button id="seed">Introduzir propágulos</button>').replace('Sem fauna, germinação, patógenos, salinidade ou arte final nesta etapa.','Coortes vegetais por célula, bancos de propágulos e polinização probabilística. Sem animais individuais, patógenos, salinidade ou arte final.').replace('1.120 células • passo de 6 horas','1.120 células • seis espécies • passo de 6 horas').replace('/*ENGINE*/',(p/'ecology.js').read_text()+'\n'+(p/'flora.js').read_text())
s=s.replace('let color=c.channel?',"let color=layer==='species'&&!c.channel?(c.sp<0?'#63523a':Flora.species[c.sp].color):layer==='phenology'&&!c.channel?({'vazio':'#63523a','plântula':'#bdd486','juvenil':'#85a957','vegetativo':'#38764e','flor':'#f3dc9a','fruto':'#d98954','esporos':'#b6a0e1'}[c.phase]):c.channel?")
s=s.replace("let legend=layer==='land'?","let legend=layer==='species'?Flora.species.map(p=>[p.color,p.name]):layer==='phenology'?Object.entries({'vazio':'#63523a','plântula':'#bdd486','juvenil':'#85a957','vegetativo':'#38764e','flor':'#f3dc9a','fruto':'#d98954','esporos':'#b6a0e1'}).map(([n,c])=>[c,n]):layer==='land'?")
s=s.replace("for(let id of ['cut','compost','water'])$(id).disabled=c.channel;", "let fm=Flora.metrics(state),ev=state.floraEvents,p=Flora.species[c.sp];$('floraStats').textContent=`${fm.richness}/6 espécies • ${fm.flowers} células em floração • ${fm.fruits} com frutos/esporos • ${ev.germinations} germinações acumuladas • ${ev.deaths} mortes • ${ev.dispersals} dispersões`;$('population').innerHTML=Flora.species.map((p,j)=>`<div><i class='dot' style='background:${p.color}'></i>${p.name}: <b>${fm.counts[j]}</b> células</div>`).join('');$('inspect').innerHTML+=`<hr><b>${p?p.name:'Sem coorte'}</b>${p?' · '+p.latin:''}<br>Fase: ${c.phase} · idade: ${Math.floor(c.age)} dias de modelo<br>Propágulos: ${c.bank.map((v,j)=>v>.001?Flora.species[j].name+' '+num(v):'').filter(Boolean).join(', ')||'nenhum'}<br>Frutos/esporos: ${num(c.fruit)}`;for(let id of ['cut','compost','water','seed'])$(id).disabled=c.channel;$('harvest').disabled=c.channel||c.phase!=='fruto';")
s=s.replace("$('weather').value='auto';$('light')","$('weather').value='auto';$('pollinators').value='normal';$('light')").replace("$('weather').onchange=", "$('pollinators').onchange=()=>state.pollinators=$('pollinators').value;$('weather').onchange=")
s=s.replace("$('weather').value=state.weather;", "$('weather').value=state.weather;$('pollinators').value=state.pollinators;")
s=s.replace("window.lab={get state(){return state},advance};update();", "$('seedSelect').innerHTML=Flora.species.map((p,i)=>`<option value='${i}'>${p.name}</option>`).join('');$('seed').onclick=()=>{if(busy)return;$('log').textContent=Flora.edit(state,sel,'seed:'+$('seedSelect').value)?'Propágulos introduzidos no banco local.':'Habitat incompatível.';update()};$('harvest').onclick=()=>{if(!busy&&Flora.edit(state,sel,'harvest')){$('log').textContent='Frutos removidos do ecossistema.';update()}};window.lab={get state(){return state},advance};update();")
(p/'ui.html').write_text(s.replace((p/'ecology.js').read_text()+'\n'+(p/'flora.js').read_text(),'/*ENGINE*/'))
